const dictionaries: Record<Language, Map<string, string>> = { en: new Map(), hi: new Map(), bn: new Map(), mr: new Map(), te: new Map(), ta: new Map(), gu: new Map() }
rows.forEach(row => { dictionaries.hi.set(row[0], row[1]); dictionaries.bn.set(row[0], row[2]); dictionaries.mr.set(row[0], row[3]); dictionaries.te.set(row[0], row[4]); dictionaries.ta.set(row[0], row[5]); dictionaries.gu.set(row[0], row[6]) })

const replaceableTerms = rows.filter(row => row[0].length > 3).sort((a, b) => b[0].length - a[0].length)

type I18nValue = { language: Language; setLanguage: (language: Language) => void; t: (key: string) => string; text: (value: string) => string; number: (value: number) => string; dateTime: (value: string | null | undefined) => string }
const I18nContext = createContext<I18nValue | null>(null)

export function I18nProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<Language>(() => {
    const saved = localStorage.getItem('disasterlens-language') as Language | null
    return languageOptions.some(option => option.code === saved) ? saved! : 'en'
  })
  const setLanguage = (next: Language) => { setLanguageState(next); localStorage.setItem('disasterlens-language', next) }
  useEffect(() => { document.documentElement.lang = language }, [language])
  const value = useMemo<I18nValue>(() => {
    const t = (key: string) => language === 'en' ? key : dictionaries[language].get(key) ?? key
    const text = (input: string) => {
      if (language === 'en') return input
      const exact = dictionaries[language].get(input)
      if (exact) return exact
      return replaceableTerms.reduce((output, row) => output.replaceAll(row[0], row[languageOptions.findIndex(option => option.code === language)]), input)
    }
    const locale = languageOptions.find(option => option.code === language)?.locale ?? 'en-IN'
    const dateTime = (input: string | null | undefined) => {
      if (!input) return '—'
      const value = new Date(input)
      if (Number.isNaN(value.getTime())) return input
      return new Intl.DateTimeFormat(locale, { dateStyle: 'medium', timeStyle: 'short', timeZone: 'Asia/Kolkata' }).format(value)
    }
    return { language, setLanguage, t, text, number: (input: number) => new Intl.NumberFormat(locale).format(input), dateTime }
  }, [language])
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>
}

export function useI18n() {
  const context = useContext(I18nContext)
  if (!context) throw new Error('useI18n must be used inside I18nProvider')
  return context
}
